	public ReturnRequest removeFromItems( UUID parentId, ReturnItem removeFrom ) {
	    LOGGER.info("handling RemoveItemsFromReturnRequestEvent " );
	
	    ReturnRequest parentEntity = repository.findById(parentId).get();
	    ReturnItem child = registry.project( ReturnItem.class, removeFrom.getReturnItemId());
	    
	    parentEntity.getItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



